import{_ as t,o as e,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"基础与模型总览","description":"","frontmatter":{"title":"基础与模型总览"},"headers":[],"relativePath":"ts-ai/foundations/index.md","filePath":"ts-ai/foundations/index.md","lastUpdated":1786083160000}'),d={name:"ts-ai/foundations/index.md"};function i(o,a,r,l,p,c){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="基础与模型总览" tabindex="-1">基础与模型总览 <a class="header-anchor" href="#基础与模型总览" aria-label="Permalink to &quot;基础与模型总览&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>本模块解决开始使用 LangChain.js 之前最容易混在一起的三类问题：运行 TypeScript AI 代码需要哪些工程基础，模型调用中究竟传入和返回了什么，以及如何写出第一批可验证的模型调用。读者不需要先学完 NestJS、Agent、RAG 或工作流。</p><h2 id="模块地图" tabindex="-1">模块地图 <a class="header-anchor" href="#模块地图" aria-label="Permalink to &quot;模块地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>负责的问题</th><th>完成后的结果</th></tr></thead><tbody><tr><td><a href="/ts-ai/foundations/getting-started/">前置与启动</a></td><td>TypeScript、Node.js、ESM、异步和运行时校验需要掌握到什么程度</td><td>能按本手册的 Node.js 22 基线创建项目，并用 Zod 校验外部数据</td></tr><tr><td><a href="/ts-ai/foundations/model/">模型基础</a></td><td>Token、上下文、消息、结构化输出、能力边界和风险如何工作</td><td>能读懂一次模型请求，判断输出是否可信并设计验证方式</td></tr><tr><td><a href="/ts-ai/foundations/langchain-bridge/">最小实践</a></td><td>LangChain.js 的模型、Prompt、结构化输出和测试 API 怎么使用</td><td>能运行、调试并测试一条完整的模型调用链</td></tr></tbody></table><p>三组内容是一条依赖链，不是三套平行入门资料：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TypeScript / Node.js 工程</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>消息、上下文与模型输出</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>ChatOpenAI.invoke()</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Prompt 模板与结构化输出</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Fake、错误注入与单元测试</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="版本与-api-约定" tabindex="-1">版本与 API 约定 <a class="header-anchor" href="#版本与-api-约定" aria-label="Permalink to &quot;版本与 API 约定&quot;">​</a></h2><p>本模块示例按下面的快照核验，核验日期为 <strong>2026-08-08</strong>。它是技术事实的复查基线，不要求读者永远安装相同补丁版本：</p><table tabindex="0"><thead><tr><th>依赖</th><th>核验版本</th><th>本模块约定</th></tr></thead><tbody><tr><td>Node.js</td><td>22 为手册统一基线</td><td>当前所用 LangChain.js 包元数据最低为 Node.js 20；手册统一使用 22，减少不同章节的运行时差异</td></tr><tr><td><code>langchain</code></td><td>1.5.5</td><td>使用 v1 顶层 API 与 <code>fakeModel()</code></td></tr><tr><td><code>@langchain/core</code></td><td>1.2.5</td><td>使用 Message、Prompt、Runnable 和标准内容块</td></tr><tr><td><code>@langchain/openai</code></td><td>1.5.6</td><td>使用 <code>ChatOpenAI</code>、Embedding 与 Structured Output</td></tr><tr><td><code>zod</code></td><td>4.4.3</td><td>示例按 Zod 4 API 编写</td></tr><tr><td>TypeScript / Vitest</td><td>7.0.2 / 4.1.10</td><td>用严格类型检查和确定性测试验收示例</td></tr></tbody></table><p>新项目安装时以实际生成的 lockfile 为准，并检查所有直接与间接依赖的 <code>engines.node</code> 交集。升级模型、网关或任一集成包后，应重新运行类型检查、单元测试和真实能力契约测试；不要只根据文章中的版本号推断兼容性。</p><p>正文第一次出现 API 时会解释输入、输出、失败和副作用；篇末速查用于回看，不替代前面的学习顺序。完整的 LangChain.js API 体系仍由后续 Agent 模块展开。</p><h2 id="推荐学习顺序" tabindex="-1">推荐学习顺序 <a class="header-anchor" href="#推荐学习顺序" aria-label="Permalink to &quot;推荐学习顺序&quot;">​</a></h2><ol><li>没写过 Node.js ESM 项目：从<a href="/ts-ai/foundations/getting-started/agent-prerequisites-map">前置知识地图</a>开始，并补齐其中标为“必须”的能力。</li><li>已熟悉 TypeScript 和 Node.js：快速完成<a href="/ts-ai/foundations/getting-started/create-typescript-ai-project">创建 TypeScript AI 项目</a>与<a href="/ts-ai/foundations/getting-started/zod-minimum-introduction">Zod 最小入门</a>。</li><li>按顺序阅读“模型基础”，先建立请求、响应和风险模型，不把框架方法当成魔法。</li><li>完成“最小实践”的四篇文章，用真实调用验证成功路径，用 <code>fakeModel()</code> 验证失败路径。</li></ol><h2 id="本模块不负责什么" tabindex="-1">本模块不负责什么 <a class="header-anchor" href="#本模块不负责什么" aria-label="Permalink to &quot;本模块不负责什么&quot;">​</a></h2><ul><li>LangChain.js 的 Runnable、Tool 与 Agent API 由<a href="/ts-ai/agent/">Agent 开发</a>展开。</li><li>NestJS 模块、Provider、接口和实时通信由<a href="/ts-ai/backend/">服务端工程</a>展开。</li><li>Embedding 的索引、检索和评测由<a href="/ts-ai/knowledge/">RAG 与记忆</a>展开。</li><li>Vue、Nuxt、SSE 和聊天界面由<a href="/ts-ai/integration/">全栈集成</a>展开。</li></ul><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><p>完成本模块时，应能提供下面这些可重复验证的证据：</p><ul><li>一个能通过 <code>npm run typecheck</code> 和 <code>npm test</code> 的 TypeScript ESM 项目；</li><li>一次真实 <code>ChatOpenAI.invoke()</code> 调用及其 <code>AIMessage</code>、Token 用量和错误日志；</li><li>一次 <code>ChatPromptTemplate</code> 渲染结果，能看见最终发送的消息顺序；</li><li>一个由 Zod 校验的结构化模型结果，以及至少一个业务校验失败样例；</li><li>一组不访问模型服务的 Fake 测试，覆盖正常响应、队列耗尽和模型异常。</li></ul>`,19)])])}const b=t(d,[["render",i]]);export{u as __pageData,b as default};
